CREATE OR REPLACE FUNCTION public.block_cart_mod_after_checkout()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_status cart_status;
BEGIN
  SELECT status INTO v_status FROM carts WHERE id = NEW.cart_id;

  IF v_status = 'checked_out' THEN
    RAISE EXCEPTION 'Cart locked';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_stock_basic()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_stock integer;
BEGIN
  SELECT stock_quantity
  INTO v_stock
  FROM items
  WHERE id = NEW.item_id;

  IF v_stock IS NULL THEN
    RAISE EXCEPTION 'Item not found';
  END IF;

  IF NEW.quantity > v_stock THEN
    RAISE EXCEPTION 'Not enough stock for item %', NEW.item_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id   uuid := (event->>'user_id')::uuid;
  v_entity_id uuid;
  v_role      text;
BEGIN
  -- Look up the user's active membership
  SELECT em.entity_id, em.role
    INTO v_entity_id, v_role
  FROM public.entity_members em
  WHERE em.profile_id = v_user_id
    AND em.is_active  = true
  ORDER BY em.joined_at ASC
  LIMIT 1;

  -- No membership found — return token unchanged (auth still succeeds)
  IF v_entity_id IS NULL THEN
    RETURN event;
  END IF;

  IF v_role IS NULL THEN
    v_role := 'user';
  END IF;

  -- Inject entity context into JWT app_metadata
  RETURN jsonb_set(
    jsonb_set(
      event,
      '{claims,app_metadata,entity_id}',
      to_jsonb(v_entity_id::text)
    ),
    '{claims,app_metadata,entity_role}',
    to_jsonb(v_role)
  );

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'custom_access_token_hook error for user %: %', v_user_id, SQLERRM;
  RETURN event;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_cart_checked_out()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Walk-in orders have no cart — skip the check
  IF NEW.is_walkin = true THEN
    RETURN NEW;
  END IF;

  IF NEW.cart_id IS NULL THEN
    RAISE EXCEPTION 'Order must reference a cart';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM carts
    WHERE id = NEW.cart_id AND status = 'checked_out'
  ) THEN
    RAISE EXCEPTION 'Cart must be checked out before creating order';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_order_placement()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Clerks may only insert walk-in orders
  IF (SELECT role FROM profiles WHERE id = auth.uid()) = 'clerk' THEN
    IF NEW.is_walkin IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'Clerks may only place walk-in orders.';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_order_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;

  IF OLD.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'Order is finalized';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_order_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO order_status_log (order_id, from_status, to_status, changed_by)
    VALUES (NEW.id, NULL, NEW.status, NEW.user_id);
  ELSE
    INSERT INTO order_status_log (order_id, from_status, to_status, changed_by)
    VALUES (NEW.id, OLD.status, NEW.status, auth.uid());
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.populate_order_item_price()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  SELECT price
  INTO NEW.unit_price_at_order
  FROM items
  WHERE id = NEW.item_id;

  IF NEW.unit_price_at_order IS NULL THEN
    RAISE EXCEPTION 'Item not found or price missing';
  END IF;

  RETURN NEW;
END;
$function$
